            var m = date.getMonth();
            var y = date.getFullYear();
            
            //need to combuine both
            var a = data[tofrom];
            var h = a.slice(0,2);
            var i = a.slice(3,5);
            // i = (i == 00)? 0 : i;
            i = (i.toString() == "00")? 0 : i;

            // $scope.myDatetimeRange.date.from = new Date(y, m, d, h, m, 0);
            // //console.log("vars are: "+y+", "+m+", "+d+", "+h+", "+i+", "+0+" soooo");
            var date = new Date(y, m, d, h, i, 0);
