        $scope.save = function(){
            var checks = [
                { ok: vm.club.settings.title,   field: 'title',   label: 'Trading As' },
                { ok: vm.club.settings.email,   field: 'email',   label: 'Email' },
                { ok: vm.club.settings.address, field: 'address', label: 'Registered Address' }
            ];
            if (vm.club.settings.vat_registered) {
                checks.push({ ok: vm.club.settings.vat_number, field: 'vat_number', label: 'VAT Number' });
                checks.push({ ok: vm.club.settings.vat_rate != null && vm.club.settings.vat_rate !== '', field: 'vat_rate', label: 'VAT Rate' });
            }
            if (!ToastService.validateForm(checks)) return;

            // opening hours: the exact contract object (a day toggled on with empty times is dropped,
            // a day toggled off is null, nothing set at all → null = not configured)
            vm.club.settings.opening_hours = vm.ohBuild();
            if (vm.ohInvalid()) {
                ToastService.warning('Opening Hours', 'Closing time must be after opening time (use 00:00 for midnight).');
                return;
            }
            // cancellation fees: {reason_key: amount} for the amounts set, null when none
            if (vm.cxf.supported) {
                if (vm.cxfInvalid()) {
                    var bad = vm.cxf.rows.filter(function(r) { return r.invalid; })[0];
                    ToastService.warning('Cancellation Fees', 'Enter an amount between 0 and 10,000, or leave it empty for no fee.');
                    // the row is already red (.cxf__row--invalid) until the amount is fixed — just take the admin there
                    var badEl = bad && document.getElementById('field-cxf-' + bad.key);
                    if (badEl) { badEl.scrollIntoView({ behavior: 'smooth', block: 'center' }); try { badEl.focus(); } catch (e) {} }
                    return;
                }
                vm.club.settings.cancellation_fees = vm.cxfChanged();
            } else {
                delete vm.club.settings.cancellation_fees;
                delete vm.club.settings.cancellation_fee_claimers;
            }

            if(!vm.club.settings.update_logo){
                    delete vm.club.settings.logo;
            }
            if(!vm.club.settings.update_invoice_logo){
                    delete vm.club.settings.invoice_logo;
            }

            if(vm.privacy_file){
                vm.club.settings.privacy_terms = vm.privacy_file;
            } else {
                delete(vm.club.settings.privacy_terms);
            }

            if(vm.membership_file){
                vm.club.settings.membership_terms = vm.membership_file;
            }else {
                delete(vm.club.settings.membership_terms);
            }

            if(vm.passenger_file){
                vm.club.settings.passenger_terms = vm.passenger_file;
            }else {
                delete(vm.club.settings.passenger_terms);
            }

            delete(vm.club.settings.membership_updated);
            delete(vm.club.settings.passenger_updated);
            delete(vm.club.settings.privacy_updated);

            delete(vm.club.settings.updated_at);
            delete(vm.club.settings.created_at);
            delete(vm.club.settings.gcl);
            delete(vm.club.settings.salt);
            delete(vm.club.settings.pepper);

            vm.club.settings.vat_registered = (vm.club.settings.vat_registered)? 1 : 0;
            vm.club.settings.tpc_aircraft_surchages = (vm.club.settings.tpc_aircraft_surchages)? 1 : 0;
            vm.club.settings.require_booking_confirmation = (vm.club.settings.require_booking_confirmation)? 1 : 0;
            vm.club.settings.hide_unavailable_instructors = (vm.club.settings.hide_unavailable_instructors)? 1 : 0;
            if (vm.findSlotGridSupported) {
                vm.club.settings.find_a_slot_grid_only = (vm.club.settings.find_a_slot_grid_only)? 1 : 0;
            } else {
                delete vm.club.settings.find_a_slot_grid_only;
            }
            // an empty / invalid amount is not sent (the backend keeps what it has)
            if (!vm.receiptReviewSupported || vm.club.settings.receipt_review_amount === null || vm.club.settings.receipt_review_amount === undefined
                || vm.club.settings.receipt_review_amount === '') {
                delete vm.club.settings.receipt_review_amount;
            }
            if (vm.paymentMethodRuleSupported) {
                vm.club.settings.require_payment_method = (vm.club.settings.require_payment_method)? 1 : 0;
            } else {
                delete vm.club.settings.require_payment_method;
            }
            if (vm.cardMachineRuleSupported) {
                vm.club.settings.card_machine_members = (vm.club.settings.card_machine_members)? 1 : 0;
            } else {
                delete vm.club.settings.card_machine_members;
            }
            if (!vm.splitTaxiSupported) { delete vm.club.settings.split_taxi_mode; }
            if (!vm.flightTracksSupported) { delete vm.club.settings.flight_tracks; }
            if (['everyone', 'staff', 'admins'].indexOf(vm.club.settings.double_booking_by) < 0) {
                vm.club.settings.double_booking_by = 'everyone';
            }
            if (!vm.claimTimesSupported) {
                delete vm.club.settings.claim_times_edit;
            } else if (['off', 'admins', 'staff'].indexOf(vm.club.settings.claim_times_edit) < 0) {
                vm.club.settings.claim_times_edit = 'off';
            }
            if (!vm.voucherRoutingSupported) {
                delete vm.club.settings.voucher_request_routing;
            } else if (['both', 'club', 'instructor'].indexOf(vm.club.settings.voucher_request_routing) < 0) {
                vm.club.settings.voucher_request_routing = 'both';
            }

            // ── Booking Edit Time Limits ──
            vm.club.settings.edit_window_admin_minutes = parseInt(vm.club.settings.edit_window_admin_minutes) || 0;
            vm.club.settings.edit_window_instructor_minutes = parseInt(vm.club.settings.edit_window_instructor_minutes) || 0;
            vm.club.settings.edit_window_member_minutes = parseInt(vm.club.settings.edit_window_member_minutes) || 0;

            // ── Membership Renewals: whole days 3–60 (an out-of-range number input leaves the model undefined) ──
            if (vm.renewalReminderSupported) {
                var rrd = vm.club.settings.renewal_reminder_days;
                if (typeof rrd !== 'number' || isNaN(rrd) || rrd % 1 !== 0 || rrd < 3 || rrd > 60) {
                    ToastService.warning('Renewal Reminder', 'Enter a whole number of days between 3 and 60.');
                    var rrdEl = document.getElementById('field-renewal_reminder_days');
                    if (rrdEl) { rrdEl.scrollIntoView({ behavior: 'smooth', block: 'center' }); try { rrdEl.focus(); } catch (e) {} }
                    return;
                }
            } else {
                delete vm.club.settings.renewal_reminder_days;
            }

            // Columns this page never edits stay out of the save: ToAviate-owned ones (fees,
            // activation, currencies, card machine — only ToAviate staff may change them),
            // payment_mode (the Payment Mode switch below), require_two_factor (ToAviate's
            // Account Security page) and server-kept ones (GoCardless / Stripe ids, switch
            // stamps, schedule version). The value read at page load can only be stale —
            // e.g. after a payment-mode switch — and the backend refuses a changed one.
            // Backend: BACKEND_CLUB_SETTINGS_ACCESS_GUIDE.md. A copy, so the page keeps
            // showing e.g. the Stripe connection if the save is refused.
            var body = angular.extend({}, vm.club.settings);
            ['app_fee', 'charge_per_flight', 'activated', 'currency', 'account_currency', 'card_machine',
             'payment_mode', 'payment_mode_switched_at', 'payment_mode_switched_by', 'require_two_factor',
             'g_id', 'stripe_id', 'schedule_version', 'created_by',
             'renewals_paused', 'renewals_paused_at', 'renewals_paused_by'].forEach(function(key) {   // ToAviate's renewals pause (super-admin hub)
                delete body[key];
            });

            ClubService.Update(body)
                .then(function(data){
                    //console.log(data);
                    // A refusal (FORBIDDEN — only the club's admins may change its settings —
                    // INVALID_UPLOAD, VALIDATION_ERROR, or an HTTP failure) keeps the page and
                    // says why; FORBIDDEN is in writeGuard's HANDLED_CODES, so nobody else toasts it.
                    if (data && data.success === false) {
                        var why = data.message;
                        if (why && typeof why === 'object') { why = why.message; }
                        ToastService.error('Settings not saved',
                            (typeof why === 'string' && why && !/^\s*</.test(why)) ? why : 'Your changes were not saved. Please try again.');
                        return;
                    }
                    // every <flight-times> on screen follows the new convention immediately
                    TimeDisplayService.setClubMode(vm.club_id, vm.club.settings.time_display);
                    $state.go('dashboard.manage_club');
                });
        }

