// ═══ Public: "STOP THIS RESET" (/two_factor_reset_cancel/:token) ═══
//  C22 (9 Nov 2026). A ToAviate administrator asked to reset the member's two-factor; the member's e-mail carries a
//  stop link. No session, no app chrome — like /email_cancel (EmailCancelController): GET only SHOWS who / when /
//  until when; the reset is stopped only by the explicit POST behind the button (mail scanners prefetch links).
//  Every failure is the backend's uniform 404 → the one "invalid or expired" panel. The API prefix is in the
//  interceptor's unauthEndpoints, the state in publicStates + publicPages (js/app.js).
//  Kept in this file (loaded on every page) so the public page needs no new <script> tag.

app.controller('TwoFactorResetCancelController', TwoFactorResetCancelController);

TwoFactorResetCancelController.$inject = ['$stateParams', 'TwoFactorService'];
function TwoFactorResetCancelController($stateParams, TwoFactorService) {
    var vm = this;
    var token = $stateParams.token;

    vm.state = 'loading';       // loading | summary | done | invalid
    vm.firstName = '';
    vm.requestedLabel = '';
    vm.holdLabel = '';
    vm.busy = false;
    vm.stop = stop;

    load();

    function load() {
        if (!token) { vm.state = 'invalid'; return; }
        TwoFactorService.ResetCancelGet(token).then(function (data) {
            if (!data || data.success === false) { vm.state = 'invalid'; return; }
            vm.firstName = data.first_name || '';
            vm.requestedLabel = label(data.requested_at);
            vm.holdLabel = label(data.hold_until);
            vm.state = 'summary';
        });
    }

    function stop() {
        if (vm.busy) { return; }
        vm.busy = true;
        TwoFactorService.ResetCancelPost(token).then(function (data) {
            vm.busy = false;
            vm.state = (data && data.success !== false) ? 'done' : 'invalid';
        });
    }

    // the API's times are UTC — shown in the reader's own time ("Mon 9 Nov 2026, 14:05")
    function label(value) {
        if (!value) { return ''; }
        if (typeof moment === 'function') {
            var m = moment.utc(String(value), 'YYYY-MM-DD HH:mm:ss');
            if (m.isValid()) { return m.local().format('ddd D MMM YYYY, HH:mm'); }
        }
        return String(value) + ' UTC';
    }
}

// ═══════════════════════════════════════════════════════════════════
//  SecuritySettingsController
//  My Account → Security — two-factor authentication (TOTP) and
//  passkeys (biometric / device sign-in). All secrets (TOTP secret,
//  recovery codes) are shown exactly once by the modals in
//  securityModalControllers.js — this screen only ever sees status.
//  Also hosts the enrolment lock: when login2 returned
//  two_factor_setup_required, the route guard in app.js pins the user
//  here until they enable 2FA or add a passkey.
//  Backend contract: FRONTEND_TWO_FACTOR_GUIDE.md
// ═══════════════════════════════════════════════════════════════════

app.controller('SecuritySettingsController', SecuritySettingsController);

SecuritySettingsController.$inject = ['TwoFactorService', 'WebauthnService', 'ToastService',
                                      '$rootScope', '$uibModal'];
function SecuritySettingsController(TwoFactorService, WebauthnService, ToastService,
                                    $rootScope, $uibModal) {
    var vm = this;

    vm.user = $rootScope.globals.currentUser;

    vm.loading = true;
    vm.status = null;              // {enabled, pending_confirmation, confirmed_at, recovery_codes_remaining, passkey_count, club_requires_two_factor}
    vm.passkeys = [];
    vm.passkeySupported = WebauthnService.isSupported();
    vm.setupRequired = false;      // club mandates 2FA and the user has nothing yet

    // MySQL datetimes ('YYYY-MM-DD HH:mm:ss') — Angular's date filter can't
    // parse them, so format via moment (global).
    vm.fmtDate = function (s) { return s ? moment(s).format('D MMM YYYY') : ''; };

    vm.openEnable     = openEnable;
    vm.openDisable    = openDisable;
    vm.openRegenerate = openRegenerate;
    vm.addPasskey     = addPasskey;
    vm.renamePasskey  = renamePasskey;
    vm.deletePasskey  = deletePasskey;

    load();

    function load() {
        vm.loading = true;
        TwoFactorService.GetStatus().then(function (data) {
            if (!data || data.success === false) {
                vm.loading = false;
                ToastService.error('Could Not Load Security Settings',
                    (data && data.message) || 'Please refresh and try again.');
                return;
            }
            vm.status = data;
            refreshSetupRequired();

            if (!vm.passkeySupported) {
                vm.loading = false;
                return;
            }
            WebauthnService.List().then(function (res) {
                vm.loading = false;
                vm.passkeys = (res && res.credentials) || [];
            });
        });
    }

    // The lock flag is set at login. Clear it as soon as the account actually
    // has a second factor (enrolled here, or reset/enrolled elsewhere).
    function refreshSetupRequired() {
        var flag = null;
        try { flag = localStorage.getItem('toaviate_2fa_setup_required'); } catch(e) {}
        var flagged = flag && String(vm.user.id) === flag;
        var hasFactor = vm.status && (vm.status.enabled || vm.status.passkey_count > 0);
        if (flagged && hasFactor) {
            clearSetupFlag();
            flagged = false;
        }
        vm.setupRequired = !!flagged;
    }

    function clearSetupFlag() {
        try { localStorage.removeItem('toaviate_2fa_setup_required'); } catch(e) {}
    }

    // ── Two-factor (TOTP) ──

    function openEnable() {
        $uibModal.open({
            windowClass: 'sec-modal-window',   // clears the fixed top nav
            templateUrl: 'views/modals/security_two_factor_enable.html',
            controller: 'TwoFactorEnableModalCtrl',
            controllerAs: 'vm',
            backdrop: 'static',
            keyboard: false
        }).result.then(function (enabled) {
            if (enabled) {
                clearSetupFlag();
                ToastService.success('Two-Factor Enabled',
                    'Your account is now protected. You will be asked for a code at every login.');
                load();
            }
        }, function () {});
    }

    function openDisable() {
        $uibModal.open({
            windowClass: 'sec-modal-window',   // clears the fixed top nav
            templateUrl: 'views/modals/security_two_factor_disable.html',
            controller: 'TwoFactorDisableModalCtrl',
            controllerAs: 'vm'
        }).result.then(function (disabled) {
            if (disabled) {
                ToastService.success('Two-Factor Disabled',
                    'Codes are no longer required at login.');
                load();
            }
        }, function () {});
    }

    function openRegenerate() {
        $uibModal.open({
            windowClass: 'sec-modal-window',   // clears the fixed top nav
            templateUrl: 'views/modals/security_recovery_codes.html',
            controller: 'RecoveryCodesModalCtrl',
            controllerAs: 'vm',
            backdrop: 'static',
            keyboard: false
        }).result.then(function (regenerated) {
            if (regenerated) { load(); }
        }, function () {});
    }

    // ── Passkeys ──

    function addPasskey() {
        $uibModal.open({
            windowClass: 'sec-modal-window',   // clears the fixed top nav
            templateUrl: 'views/modals/security_passkey_add.html',
            controller: 'PasskeyAddModalCtrl',
            controllerAs: 'vm',
            backdrop: 'static'
        }).result.then(function (added) {
            if (added) {
                clearSetupFlag();
                ToastService.success('Passkey Added',
                    'You can now sign in with this device\'s biometrics or PIN.');
                load();
            }
        }, function () {});
    }

    function renamePasskey(passkey) {
        $uibModal.open({
            windowClass: 'sec-modal-window',   // clears the fixed top nav
            templateUrl: 'views/modals/security_passkey_rename.html',
            controller: 'PasskeyRenameModalCtrl',
            controllerAs: 'vm',
            resolve: { passkey: function () { return passkey; } }
        }).result.then(function (renamed) {
            if (renamed) { load(); }
        }, function () {});
    }

    function deletePasskey(passkey) {
        $uibModal.open({
            windowClass: 'sec-modal-window',   // clears the fixed top nav
            templateUrl: 'views/modals/security_passkey_delete.html',
            controller: 'PasskeyDeleteModalCtrl',
            controllerAs: 'vm',
            resolve: { passkey: function () { return passkey; } }
        }).result.then(function (removed) {
            if (removed) {
                ToastService.success('Passkey Removed', 'That passkey can no longer be used to sign in.');
                load();
            }
        }, function () {});
    }
}

// ─────────────────────────────────────────────────────
// ShareAssignmentModalController — instructor shares a questionnaire/material
// with one or more students (message + optional due date). Used via $uibModal.
// Resolves: clubId, item ({type, id, title}), context ({attach_type, attach_id,
// timing, course_sitting_id, course_id}).
// ─────────────────────────────────────────────────────
app.controller('ShareAssignmentModalController', ShareAssignmentModalController);

    ShareAssignmentModalController.$inject = ['$uibModalInstance', 'CourseAssignmentService', 'MemberService', 'ToastService', '$q', 'clubId', 'item', 'context'];
    function ShareAssignmentModalController($uibModalInstance, CourseAssignmentService, MemberService, ToastService, $q, clubId, item, context) {
        var m = this;
        m.item = item;                 // { type, id, title }
        m.context = context || {};
        m.loadingStudents = true;
        m.students = [];               // all club members
        m.selected = [];               // chosen students
        m.message = '';
        m.dueDate = null;
        m.sendEmail = true;

        (MemberService.GetAllByClub ? MemberService.GetAllByClub(clubId) : $q.when([])).then(function(data) {
            m.loadingStudents = false;
            var members = (data && data.members) ? data.members : (angular.isArray(data) ? data : []);
            m.students = members.map(function(mem) {
                return { id: mem.user_id || mem.id, name: ((mem.first_name || '') + ' ' + (mem.last_name || '')).trim(), email: mem.email || '' };
            }).filter(function(s) { return s.id; });
        });

        // ui-select multiple gives us m.selected directly; keep a removeable chip list.
        m.removeStudent = function(s) {
            m.selected = m.selected.filter(function(x) { return x.id !== s.id; });
        };

        function ymd(d) {
            if (!d) return null;
            if (typeof d === 'string') return d.slice(0, 10);
            var y = d.getFullYear(), mo = ('0' + (d.getMonth() + 1)).slice(-2), da = ('0' + d.getDate()).slice(-2);
            return y + '-' + mo + '-' + da;
        }

        m.share = function() {
            if (!m.selected.length) { ToastService.warning('Pick a student', 'Choose at least one student to share with.'); return; }
            var payload = {
                item_type: m.item.type,
                item_id: m.item.id,
                student_ids: m.selected.map(function(s) { return s.id; }),
                message: m.message || '',
                due_date: ymd(m.dueDate),
                send_email: m.sendEmail ? true : false
            };
            // Carry the course/lesson context so the deep link + attempt bind correctly.
            ['attach_type', 'attach_id', 'timing', 'course_sitting_id', 'course_id'].forEach(function(k) {
                if (m.context[k] != null && m.context[k] !== '') payload[k] = m.context[k];
            });
            submit(payload, false);
        };

        // ── Re-assign confirmation ──
        // The backend returns needs_confirm:true (NOT an error) when a student in
        // results[] has already_completed:true. We surface its message and, on
        // confirm, re-POST the identical payload with confirm:true — which re-assigns
        // and grants a fresh blank attempt (the old one is preserved). confirm:true
        // is idempotent-friendly, so re-sending all students is safe.
        m.confirmNeeded = false;
        m.confirmMessage = '';
        var pendingPayload = null;

        function submit(payload, confirmed) {
            m.sharing = true;
            if (confirmed) payload.confirm = true;
            CourseAssignmentService.Share(payload).then(function(data) {
                m.sharing = false;

                if (data && data.needs_confirm && !confirmed) {
                    // Not an error — ask the instructor, then retry with confirm:true.
                    pendingPayload = payload;
                    m.confirmMessage = data.message ||
                        'One or more students have already completed this. Re-assign anyway? A fresh retake will be granted.';
                    m.confirmNeeded = true;
                    return;
                }

                m.confirmNeeded = false;
                if (!data || data.success === false) { ToastService.error('Could not share', (data && data.message) || ''); return; }
                var shared = data.shared || (data.results ? data.results.length : m.selected.length);
                var emailed = (data.results || []).filter(function(r) { return r.emailed; }).length;
                ToastService.success('Shared with ' + shared + ' student' + (shared === 1 ? '' : 's'),
                    m.sendEmail ? (emailed + ' notified by email.') : 'Added to their tasks (no email).');
                $uibModalInstance.close(data);
            });
        }

        m.confirmReassign = function() {
            if (!pendingPayload) return;
            submit(pendingPayload, true);
        };
        m.cancelReassign = function() {
            m.confirmNeeded = false;
            pendingPayload = null;
        };

        m.cancel = function() { $uibModalInstance.dismiss('cancel'); };
    }

