// ═══════════════════════════════════════════════════════════════════
//  TrainingRecordReassignController — bulk "this belongs to another
//  course" repair for training records.
//  Contract: BACKEND_TRAINING_RECORD_COURSE_GUIDE.md (Part B).
//
//  Why it exists: the workbook importer resolves a record's course from
//  the free-text exercise cell and falls back to the club's default (PPL)
//  course when it can't tell — so IMC / night / type / check flights get
//  filed under PPL. This finds them and moves them, optionally setting a
//  lesson (otherwise the instructor sets it on the record as usual).
//  Embedded in Settings → Data Import. Club managers only.
// ═══════════════════════════════════════════════════════════════════

app.controller('TrainingRecordReassignController', TrainingRecordReassignController);

    TrainingRecordReassignController.$inject = ['TpcImportService', 'CourseService', 'MemberService', 'PlaneService', 'ToastService', '$rootScope', '$timeout'];
    function TrainingRecordReassignController(TpcImportService, CourseService, MemberService, PlaneService, ToastService, $rootScope, $timeout) {

        var vm = this;
        var PER_PAGE = 50;
        var MOVE_BATCH = 500;   // backend caps record_ids per call

        vm.user = $rootScope.globals.currentUser;
        vm.club_id = vm.user.current_club_admin && vm.user.current_club_admin.id;
        vm.is_manager = (vm.user.access.manager || []).indexOf(vm.club_id) > -1 ||
                        (vm.user.access.super_admin || []).length > 0;
        if (!vm.is_manager) { return; }

        vm.open = false;          // the whole tool is collapsed until asked for
        vm.courses = [];
        vm.students = [];
        vm.planes = [];
        // ui-select binds objects; the filters below carry the plain values.
        vm.pick = { student: null, plane: null };
        vm.loading = false;
        vm.moving = false;
        vm.searched = false;
        vm.rows = [];
        vm.total = 0;
        vm.page = 1;

        // Search filters. imported_only defaults ON — this is a repair tool
        // for importer mistakes, and it keeps hand-made records out of the way.
        vm.f = {
            course_id: null, student_user_id: null, lesson_id: null,
            from: null, to: null, registration: '', q: '', imported_only: 1
        };

        // Move target.
        vm.target = { course_id: null, lesson_id: null };

        vm.sel = {};              // id → true
        vm.lastResult = null;

        vm.toggleOpen = function() {
            vm.open = !vm.open;
            if (vm.open && !vm.courses.length) { loadPickers(); }
        };

        function loadPickers() {
            TpcImportService.CoursesForClub(vm.club_id).then(function(data) {
                vm.courses = CourseService.sortByDisplayOrder((data && data.courses) || []);
            });
            MemberService.GetAllByClub(vm.club_id).then(function(data) {
                var list = angular.isArray(data) ? data : (data && data.members) || [];
                vm.students = list.map(function(m) {
                    return {
                        id: m.user_id || m.id,
                        name: ((m.first_name || '') + ' ' + (m.last_name || '')).trim()
                    };
                }).filter(function(s) { return s.id && s.name; });
            });
            PlaneService.GetAllByClub(vm.club_id).then(function(data) {
                var list = angular.isArray(data) ? data : (data && data.planes) || [];
                vm.planes = list.map(function(p) {
                    return {
                        registration: p.registration,
                        label: p.registration + (p.plane_type ? ' · ' + p.plane_type : '')
                    };
                }).filter(function(p) { return p.registration; });
            });
        }

        // ui-select → filter value (clearing the pick clears the filter).
        vm.onStudentPick = function(item) {
            vm.f.student_user_id = item ? item.id : null;
            vm.search(1);
        };
        vm.onPlanePick = function(item) {
            vm.f.registration = item ? item.registration : '';
            vm.search(1);
        };

        vm.lessonsFor = function(course_id) {
            for (var i = 0; i < vm.courses.length; i++) {
                if (String(vm.courses[i].id) === String(course_id)) { return vm.courses[i].lessons || []; }
            }
            return [];
        };
        vm.onTargetCourseChange = function() {
            var ok = false;
            vm.lessonsFor(vm.target.course_id).forEach(function(l) {
                if (String(l.id) === String(vm.target.lesson_id)) { ok = true; }
            });
            if (!ok) { vm.target.lesson_id = null; }
        };
        vm.courseTitle = function(id) {
            for (var i = 0; i < vm.courses.length; i++) {
                if (String(vm.courses[i].id) === String(id)) { return vm.courses[i].title; }
            }
            return '';
        };

        // Debounced free-text search so typing doesn't hammer the endpoint.
        var debounce = null;
        vm.searchSoon = function() {
            if (debounce) { $timeout.cancel(debounce); }
            debounce = $timeout(function() { vm.search(1); }, 350);
        };

        vm.search = function(page) {
            vm.page = page || 1;
            vm.loading = true;
            vm.searched = true;
            var params = angular.extend({}, vm.f, {
                club_id: vm.club_id,
                page: vm.page,
                per_page: PER_PAGE
            });
            TpcImportService.SearchRecords(params).then(function(data) {
                vm.loading = false;
                if (!data || data.success === false) {
                    ToastService.error('Search Failed', (data && data.message) || 'The records could not be searched.');
                    vm.rows = []; vm.total = 0;
                    return;
                }
                vm.rows = data.items || [];
                vm.total = data.total || 0;
                vm.sel = {};   // selection never survives a new search
            });
        };

        vm.pages = function() { return Math.max(1, Math.ceil(vm.total / PER_PAGE)); };
        vm.goPage = function(p) {
            if (p < 1 || p > vm.pages() || vm.loading) { return; }
            vm.search(p);
        };

        // ── Selection ──
        vm.selCount = function() { return vm.selIds().length; };
        vm.selIds = function() {
            return Object.keys(vm.sel).filter(function(k) { return vm.sel[k]; }).map(Number);
        };
        vm.allOnPage = function() {
            if (!vm.rows.length) { return false; }
            for (var i = 0; i < vm.rows.length; i++) { if (!vm.sel[vm.rows[i].id]) { return false; } }
            return true;
        };
        vm.toggleAll = function() {
            var on = !vm.allOnPage();
            vm.rows.forEach(function(r) { vm.sel[r.id] = on; });
        };

        // ── Move ──
        vm.canMove = function() {
            return !vm.moving && vm.selCount() > 0 && !!vm.target.course_id;
        };
        vm.move = function() {
            if (!vm.canMove()) { return; }
            var ids = vm.selIds();
            vm.moving = true;
            vm.lastResult = null;
            var moved = 0, skipped = 0, i = 0;

            (function nextBatch() {
                if (i >= ids.length) {
                    vm.moving = false;
                    vm.lastResult = { moved: moved, skipped: skipped, course: vm.courseTitle(vm.target.course_id) };
                    ToastService.success('Records Moved',
                        moved + ' record(s) moved to ' + vm.lastResult.course +
                        (skipped ? ' · ' + skipped + ' skipped' : '') + '.');
                    vm.search(vm.page);   // refresh — moved rows may drop out of the filter
                    return;
                }
                var batch = ids.slice(i, i + MOVE_BATCH);
                i += MOVE_BATCH;
                TpcImportService.ReassignRecords(vm.club_id, batch, vm.target.course_id, vm.target.lesson_id)
                    .then(function(data) {
                        if (!data || data.success === false) {
                            vm.moving = false;
                            ToastService.error('Move Failed', (data && data.message) || 'The records could not be moved.');
                            return;
                        }
                        var r = data.result || {};
                        moved += r.moved || 0;
                        skipped += r.skipped || 0;
                        nextBatch();
                    });
            })();
        };
    }

    app.controller('UpcomingBookingsController', UpcomingBookingsController);

    UpcomingBookingsController.$inject = ['BookingService', 'ToastService', '$rootScope', '$scope', '$state', '$timeout'];
    function UpcomingBookingsController(BookingService, ToastService, $rootScope, $scope, $state, $timeout) {

        var vm = this;

        // ── State ──
        vm.user = $rootScope.globals.currentUser;
        vm.bookings = [];
        vm.filteredBookings = [];
        vm.groupedBookings = [];
        vm.clubs = [];          // unique clubs from results
        vm.selectedClubId = ''; // '' = all clubs
        vm.searchText = '';
        vm.loading = true;
        vm.loadingMore = false;
        vm.showDetail = false;
        vm.selectedBooking = null;
        vm.nextBooking = null;
        vm.clubCount = 0;

        vm.pagination = {
            page: 1,
            per_page: 20,
            total: 0,
            total_pages: 0,
            has_more: false
        };

        // ── Public methods ──
        vm.loadMore = loadMore;
        vm.filterByClub = filterByClub;
        vm.filterBookings = filterBookings;
        vm.viewBooking = viewBooking;
        vm.viewOnScheduler = viewOnScheduler;
        vm.viewHistory = viewHistory;
        vm.closeDetail = closeDetail;

        // ── Init ──
        activate();

        // ────────────────────────────────────────────
        function activate() {
            loadBookings(false);
        }

        function loadBookings(append) {
            if (append) {
                vm.loadingMore = true;
            } else {
                vm.loading = true;
            }

            var clubId = vm.selectedClubId ? parseInt(vm.selectedClubId) : null;

            BookingService.GetUpcoming(vm.user.id, vm.pagination.page, vm.pagination.per_page, clubId)
                .then(function(data) {
                    vm.loading = false;
                    vm.loadingMore = false;

                    if (!data.success) {
                        ToastService.error(data.message || 'Failed to load bookings');
                        return;
                    }

                    if (append) {
                        vm.bookings = vm.bookings.concat(data.bookings);
                    } else {
                        vm.bookings = data.bookings || [];
                    }

                    vm.pagination = data.pagination || vm.pagination;

                    // Derive clubs list from all loaded bookings
                    buildClubsList();

                    // Set summary info
                    if (vm.bookings.length > 0) {
                        vm.nextBooking = vm.bookings[0];
                    }

                    // Apply search filter
                    filterBookings();
                })
                .catch(function() {
                    vm.loading = false;
                    vm.loadingMore = false;
                    ToastService.error('Failed to load bookings. Please try again.');
                });
        }

        function loadMore() {
            if (vm.loadingMore || !vm.pagination.has_more) return;
            vm.pagination.page++;
            loadBookings(true);
        }

        function filterByClub() {
            vm.bookings = [];
            vm.pagination.page = 1;
            loadBookings(false);
        }

        function filterBookings() {
            var search = (vm.searchText || '').toLowerCase();

            if (!search) {
                vm.filteredBookings = vm.bookings;
            } else {
                vm.filteredBookings = vm.bookings.filter(function(b) {
                    return (
                        (b.plane_registration && b.plane_registration.toLowerCase().indexOf(search) !== -1) ||
                        (b.plane_type && b.plane_type.toLowerCase().indexOf(search) !== -1) ||
                        (b.instructor_name && b.instructor_name.toLowerCase().indexOf(search) !== -1) ||
                        (b.student_name && b.student_name.toLowerCase().indexOf(search) !== -1) ||
                        (b.club_name && b.club_name.toLowerCase().indexOf(search) !== -1) ||
                        (b.description && b.description.toLowerCase().indexOf(search) !== -1)
                    );
                });
            }

            groupByDate();
        }

        function groupByDate() {
            var groups = {};
            var order = [];

            vm.filteredBookings.forEach(function(b) {
                if (!groups[b.date]) {
                    groups[b.date] = {
                        date: b.date,
                        day: b.day,
                        dateFormatted: formatDateNice(b.date),
                        bookings: []
                    };
                    order.push(b.date);
                }
                groups[b.date].bookings.push(b);
            });

            vm.groupedBookings = order.map(function(d) { return groups[d]; });
        }

        function buildClubsList() {
            var seen = {};
            var clubs = [];
            vm.bookings.forEach(function(b) {
                if (b.club_id && !seen[b.club_id]) {
                    seen[b.club_id] = true;
                    clubs.push({ id: b.club_id, name: b.club_name });
                }
            });
            // Only update clubs list if we got new clubs (don't lose clubs on filter)
            if (clubs.length > 0) {
                vm.clubs = clubs;
            }
            vm.clubCount = vm.clubs.length;
        }

        function viewBooking(booking) {
            vm.selectedBooking = booking;
            vm.showDetail = true;
        }

        function closeDetail() {
            vm.showDetail = false;
            vm.selectedBooking = null;
        }

        function viewOnScheduler(booking) {
            // Navigate to the scheduler/edit booking route
            $state.go('dashboard.edit_booking', { booking_id: booking.id });
        }

        function viewHistory(booking) {
            $state.go('dashboard.my_account.booking_audit_trail', { booking_id: booking.id });
        }

        function formatDateNice(dateStr) {
            // dateStr is YYYY-MM-DD
            if (!dateStr) return '';
            var parts = dateStr.split('-');
            var d = new Date(parts[0], parts[1] - 1, parts[2]);
            var months = ['January', 'February', 'March', 'April', 'May', 'June',
                          'July', 'August', 'September', 'October', 'November', 'December'];
            var today = new Date();
            today.setHours(0, 0, 0, 0);
            var tomorrow = new Date(today);
            tomorrow.setDate(tomorrow.getDate() + 1);

            if (d.getTime() === today.getTime()) {
                return 'Today, ' + d.getDate() + ' ' + months[d.getMonth()];
            } else if (d.getTime() === tomorrow.getTime()) {
                return 'Tomorrow, ' + d.getDate() + ' ' + months[d.getMonth()];
            }
            return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear();
        }

    }

