/* the aircraft model on the v2 booked-out page, tidied (UX pass 2): "PIPER AIRCRAFT CORPORATION CADET" → "Piper Cadet".
   Same choice of words as bodPlaneModel (js/directives/bodCountdown.js, shared with v1 — left alone), then the company
   words dropped from the manufacturer and registry capitals title-cased (short words like "II" / "DA" and anything with a
   digit — "PA-28-161", "C152" — stay as they are). */
app.filter('bov2PlaneModel', function () {
    var COMPANY = /^(aircraft|aviation|aeroplanes?|airplanes?|corporation|corp|company|co|inc|incorporated|ltd|limited|llc|gmbh|sa|plc|industries|international|group)\.?,?$/i;
    function clean(v) { return (v === null || v === undefined) ? '' : String(v).replace(/^\s+|\s+$/g, ''); }
    function tidy(w) { return (/^[A-Z]{4,}$/.test(w)) ? w.charAt(0) + w.slice(1).toLowerCase() : w; }
    return function (p) {
        if (!p) { return ''; }
        var man = clean(p.manufacturer).split(/\s+/).filter(Boolean), type = clean(p.type_name);
        while (man.length > 1 && COMPANY.test(man[man.length - 1])) { man.pop(); }
        var m = man.join(' '), out;
        if (m && type && type.toLowerCase().indexOf(m.toLowerCase()) === 0) { out = type; } else { out = clean(m + ' ' + type); }
        out = out || clean(p.plane_type) || clean(p.type);
        return out.split(/\s+/).map(tidy).join(' ');
    };
});

