                if (p.status == 'accepted') { return 'Accepted'; }
                if (p.status == 'invited') { return 'Invited — awaiting reply'; }
                if (p.status == 'to_invite') { return 'Not invited yet'; }
                if (p.status == 'declined') { return 'Declined'; }
