            return { k: k, lab: yearly ? k : F.MON[mo], s: yearly ? k.slice(2) : F.MON[mo][0], long: yearly ? k : F.MONTH[mo] + ' ' + k.slice(0, 4), total: t.total_time, pic: t.pic_time, flights: rows.length };
