    S.term = function (t) { return TERMS[String(t || '').toLowerCase()] || null; };
    S.isFree = function (o) { var t = String(o.payment_term || '').toLowerCase(); return t === 'free' || (o.price !== undefined && o.price !== null && o.price !== '' && S.num(o.price) === 0); };
