        if (ck && ck.length) {
            return ck.every(function (c) { return c.verified; }) ? { tone: 'good', label: 'Checked by your clubs', icon: 'fa-check-circle' } : { tone: 'pend', label: 'Awaiting a check', icon: 'fa-hourglass-half' };
        }
